const $=id=>document.getElementById(id);
const storage={get(key,fallback=null){try{return JSON.parse(localStorage.getItem(`metorbike:${key}`))??fallback;}catch{return fallback;}},set(key,value){try{localStorage.setItem(`metorbike:${key}`,JSON.stringify(value));}catch{/* A race also works with browser storage disabled. */}}};
let renderer;
try{renderer=new THREE.WebGLRenderer({antialias:window.devicePixelRatio<2,alpha:false,powerPreference:'high-performance'});}catch(error){$('loading').classList.add('hidden');$('webgl-error').classList.remove('hidden');throw error;}
renderer.setPixelRatio(Math.min(window.devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;$('scene').appendChild(renderer.domElement);
const camera=new THREE.PerspectiveCamera(46,innerWidth/innerHeight,.1,2300);
const environment=studioEnvironment(renderer);
const showroom=createShowroom();showroom.scene.environment=environment;showroom.bike.scale.setScalar(1.3);let activeScene=showroom.scene;
let selectedTrack=storage.get('track','kart');if(!['kart','star'].includes(selectedTrack))selectedTrack='kart';
let selectedColor=clamp(storage.get('color',0),0,3);
let selectedConfig=normalizeBikeConfig(storage.get('bike-config',{})),garageRotation=0,rotationDrag=null,birdFarewell=0;
let mode='garage',race=null,world=null,data=null,playerBike=null,botBikes=[],countdown=0,lastCount=-1,elapsed=0,accumulator=0,viewTime=0,messageTimer=0,finishShown=false;
let steerPointer=null,touchSteer=0,controlPointers=new Map();
const keys=new Set(),touch={gas:false,brake:false,boost:false};
const mapCtx=$('minimap').getContext('2d');let minimapPoints=[],mapBounds=null;
let sound=storage.get('sound',true),audio=null;
const engine={
  unlock(){if(audio){audio.ctx.resume().catch(()=>{});return;}try{const ctx=new (window.AudioContext||window.webkitAudioContext)();const master=ctx.createGain();master.gain.value=sound?.16:0;master.connect(ctx.destination);const gain=ctx.createGain();gain.gain.value=0;gain.connect(master);const osc=ctx.createOscillator();osc.type='triangle';osc.frequency.value=45;osc.connect(gain);osc.start();const higher=ctx.createOscillator();higher.type='sine';higher.frequency.value=90;higher.connect(gain);higher.start();audio={ctx,master,gain,osc,higher};}catch{/* Audio is optional. */}},
  update(){if(!audio)return;const driving=mode==='race';const speed=race?.player.speed||0;audio.master.gain.setTargetAtTime(sound?.16:0,audio.ctx.currentTime,.07);audio.gain.gain.setTargetAtTime(driving?.09+speed*.006:0,audio.ctx.currentTime,.1);audio.osc.frequency.setTargetAtTime(40+speed*4,audio.ctx.currentTime,.06);audio.higher.frequency.setTargetAtTime(82+speed*7.6,audio.ctx.currentTime,.06);},
  beep(frequency=600,duration=.12){if(!sound)return;this.unlock();if(!audio)return;const o=audio.ctx.createOscillator(),g=audio.ctx.createGain();o.type='sine';o.frequency.value=frequency;g.gain.value=.22;g.gain.exponentialRampToValueAtTime(.001,audio.ctx.currentTime+duration);o.connect(g);g.connect(audio.master);o.start();o.stop(audio.ctx.currentTime+duration);}
};
function soundButtons(){document.querySelectorAll('.sound-toggle').forEach(b=>{b.innerHTML=sound?'<svg viewBox="0 0 24 24"><path d="M4 9h4l5-4v14l-5-4H4zM16 8q5 4 0 8M18 5q9 7 0 14"/></svg>':'<svg viewBox="0 0 24 24"><path d="M4 9h4l5-4v14l-5-4H4zM17 9l5 6m0-6l-5 6"/></svg>';b.setAttribute('aria-label',sound?'Ton ausschalten':'Ton einschalten');b.title=sound?'Ton ausschalten':'Ton einschalten';b.setAttribute('aria-pressed',String(sound));});}
document.querySelectorAll('.sound-toggle').forEach(b=>b.addEventListener('click',()=>{sound=!sound;if(!sound)window.speechSynthesis?.cancel();storage.set('sound',sound);engine.unlock();soundButtons();}));
document.querySelectorAll('.fullscreen-toggle').forEach(b=>b.addEventListener('click',async()=>{try{if(!document.fullscreenElement){await document.documentElement.requestFullscreen();if(matchMedia('(pointer:coarse)').matches)await screen.orientation?.lock?.('landscape').catch(()=>{});}else await document.exitFullscreen();}catch{showMessage('Vollbild über das Browsermenü öffnen');}}));
function chooseTrack(id){selectedTrack=id;storage.set('track',id);document.querySelectorAll('[data-track]').forEach(b=>{const active=b.dataset.track===id;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});}
function rebuildShowroomBike(){const previous=showroom.bike;showroom.scene.remove(previous);disposeBike(previous);showroom.bike=makeBike(selectedColor,selectedConfig.passenger,selectedConfig);showroom.bike.scale.setScalar(1.3);showroom.scene.add(showroom.bike);}
function chooseColor(i){selectedColor=i;storage.set('color',i);rebuildShowroomBike();$('bike-name').textContent=BIKE_COLORS[i].name;$('hero-bike-name').textContent=`${selectedConfig.powerClass} kW · ${BIKE_COLORS[i].name}`;document.querySelectorAll('[data-color]').forEach(b=>{const active=Number(b.dataset.color)===i;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}
function chooseConfig(changes={}){selectedConfig=normalizeBikeConfig({...selectedConfig,...changes});storage.set('bike-config',selectedConfig);$('seat-select').value=selectedConfig.seat;$('leather-select').value=selectedConfig.leather;$('passenger-select').value=selectedConfig.passenger?'passenger':'solo';document.querySelectorAll('[data-power]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.power)===selectedConfig.powerClass)));$('config-note').replaceChildren(document.createTextNode(`${selectedConfig.powerClass} kW · ${selectedConfig.powerClass===4?'Mehr Punch. Mehr Tempo.':'Entspannt einsteigen.'}`));const hint=document.createElement('span');hint.textContent=selectedConfig.passenger?'Beifahrer an Bord · Doppelsitz aktiv':'Arcade-Fahrwerte · eigene Bestzeiten je Klasse';$('config-note').append(hint);chooseColor(selectedColor);}
document.querySelectorAll('[data-power]').forEach(b=>b.addEventListener('click',()=>chooseConfig({powerClass:Number(b.dataset.power)})));$('seat-select').addEventListener('change',e=>chooseConfig({seat:e.target.value,passenger:e.target.value==='double'&&selectedConfig.passenger}));$('leather-select').addEventListener('change',e=>chooseConfig({leather:e.target.value}));$('passenger-select').addEventListener('change',e=>chooseConfig({passenger:e.target.value==='passenger'}));
function rotateBike(angle){garageRotation=wrap(angle,Math.PI*2);$('bike-rotation').value=String(Math.round(garageRotation/Math.PI*180));}
$('rotate-left').addEventListener('click',()=>rotateBike(garageRotation-Math.PI/6));$('rotate-right').addEventListener('click',()=>rotateBike(garageRotation+Math.PI/6));$('rotate-reset').addEventListener('click',()=>rotateBike(0));$('bike-rotation').addEventListener('input',e=>rotateBike(Number(e.target.value)*Math.PI/180));
const viewer=$('bike-viewer');viewer.addEventListener('pointerdown',e=>{rotationDrag={id:e.pointerId,x:e.clientX,angle:garageRotation};viewer.setPointerCapture(e.pointerId);});viewer.addEventListener('pointermove',e=>{if(rotationDrag?.id===e.pointerId)rotateBike(rotationDrag.angle+(e.clientX-rotationDrag.x)*.012);});for(const event of ['pointerup','pointercancel','lostpointercapture'])viewer.addEventListener(event,()=>rotationDrag=null);viewer.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();rotateBike(garageRotation+(e.key==='ArrowLeft'?-1:1)*Math.PI/12);}if(e.key==='Home'){e.preventDefault();rotateBike(0);}});
document.querySelectorAll('[data-track]').forEach(b=>b.addEventListener('click',()=>chooseTrack(b.dataset.track)));document.querySelectorAll('[data-color]').forEach(b=>b.addEventListener('click',()=>chooseColor(Number(b.dataset.color))));
chooseTrack(selectedTrack);chooseConfig();soundButtons();
$('help-button').addEventListener('click',()=>$('help-dialog').showModal());for(const id of ['close-help','help-ready'])$(id).addEventListener('click',()=>$('help-dialog').close());$('help-dialog').addEventListener('click',e=>{if(e.target===$('help-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function clearInput(){keys.clear();touch.gas=touch.brake=touch.boost=false;touchSteer=0;steerPointer=null;controlPointers.clear();$('steer-knob').style.transform='';for(const b of document.querySelectorAll('.pedals button'))b.style.filter='';}
function input(){return{gas:keys.has('KeyW')||keys.has('ArrowUp')||touch.gas,brake:keys.has('KeyS')||keys.has('ArrowDown')||touch.brake,steer:touchSteer||((keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)),boost:keys.has('ShiftLeft')||keys.has('ShiftRight')||keys.has('Space')||touch.boost};}
function showMessage(text,duration=2){$('race-message').textContent=text;$('race-message').classList.add('visible');messageTimer=duration;}
function raceStart(){
  clearInput();engine.unlock();$('start-button').disabled=true;$('start-button').firstElementChild.textContent='STRECKE WIRD GELADEN …';
  // Let the button repaint before creating the 3D world.
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    try{
      if(world)disposeWorld(world.scene);
      data=trackData(selectedTrack);world=createRaceWorld(data);world.scene.environment=environment;world.parrot=makeParrot();world.scene.add(world.parrot);birdFarewell=0;race=new Race(data,data.curvature,selectedConfig);playerBike=makeBike(selectedColor,true,selectedConfig);world.scene.add(playerBike);botBikes=race.bots.map((b,i)=>{const bike=makeBike(b.colorIndex,true,{powerClass:selectedConfig.powerClass,seat:i%2?'hump':'single',leather:i%2?'black':'brown'});world.scene.add(bike);return bike;});
      activeScene=world.scene;mode='countdown';countdown=3.5;lastCount=-1;accumulator=0;finishShown=false;elapsed=0;
      $('garage').classList.add('hidden');$('race-ui').classList.remove('hidden');$('pause-overlay').classList.add('hidden');$('results-overlay').classList.add('hidden');document.body.classList.add('racing');$('hud-track-name').textContent=data.name.toUpperCase();$('hud-lap').textContent='RUNDE 1 / 3';$('race-message').classList.remove('visible');
      $('hud-track-name').textContent=`${data.name.toUpperCase()} · ${selectedConfig.powerClass} kW`;$('parrot-caption').classList.add('hidden');$('stunt-label').classList.remove('active');window.speechSynthesis?.cancel();const best=storage.get(recordKey(selectedTrack,selectedConfig));$('best-time').textContent=`BESTE ZEIT ${best?formatTime(best):'—'}`;
      prepareMinimap();updateRacerModels(1/60);updateCamera(1,true);updateHud();$('pause-button').focus({preventScroll:true});
      if(matchMedia('(pointer:coarse)').matches&&innerHeight>innerWidth)pauseRace();
    }catch(error){console.error('Race could not be created:',error);returnToGarage();$('start-button').firstElementChild.textContent='ERNEUT VERSUCHEN';}
    $('start-button').disabled=false;$('start-button').firstElementChild.textContent='RENNEN STARTEN';
  }));
}
let beforePause='race';
function pauseRace(){if(!['race','countdown'].includes(mode))return;beforePause=mode;mode='paused';clearInput();window.speechSynthesis?.cancel();$('pause-overlay').classList.remove('hidden');$('resume-button').focus({preventScroll:true});}
function resumeRace(){if(mode!=='paused')return;if(matchMedia('(pointer:coarse)').matches&&innerHeight>innerWidth)return;clearInput();mode=beforePause;accumulator=0;$('pause-overlay').classList.add('hidden');engine.unlock();}
function returnToGarage(){mode='garage';clearInput();window.speechSynthesis?.cancel();activeScene=showroom.scene;$('garage').classList.remove('hidden');$('race-ui').classList.add('hidden');$('pause-overlay').classList.add('hidden');$('results-overlay').classList.add('hidden');document.body.classList.remove('racing');$('countdown').textContent='';$('parrot-caption').classList.add('hidden');$('start-button').focus({preventScroll:true});window.scrollTo(0,0);}
$('start-button').addEventListener('click',raceStart);$('pause-button').addEventListener('click',pauseRace);$('resume-button').addEventListener('click',resumeRace);$('restart-button').addEventListener('click',raceStart);$('garage-button').addEventListener('click',returnToGarage);$('again-button').addEventListener('click',raceStart);$('finish-garage-button').addEventListener('click',returnToGarage);
window.addEventListener('keydown',e=>{if(mode==='garage')return;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','ShiftLeft','ShiftRight','Space','Escape','KeyP','KeyR'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'||e.code==='KeyP'){mode==='paused'?resumeRace():pauseRace();return;}if(e.code==='KeyR'&&mode==='race'){if(race.resetPlayer())showMessage('ZURÜCK AUF KURS',1);}keys.add(e.code);});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',pauseRace);document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseRace();});
const pad=$('steer-pad');pad.addEventListener('pointerdown',e=>{if(steerPointer!==null)return;e.preventDefault();steerPointer=e.pointerId;pad.setPointerCapture(e.pointerId);moveStick(e);});pad.addEventListener('pointermove',e=>{if(e.pointerId===steerPointer)moveStick(e);});function moveStick(e){const r=pad.getBoundingClientRect();touchSteer=clamp((e.clientX-r.left-r.width/2)/(r.width*.34),-1,1);$('steer-knob').style.transform=`translateX(${touchSteer*r.width*.24}px)`;}
function releaseStick(e){if(e.pointerId===steerPointer){steerPointer=null;touchSteer=0;$('steer-knob').style.transform='';}}pad.addEventListener('pointerup',releaseStick);pad.addEventListener('pointercancel',releaseStick);pad.addEventListener('lostpointercapture',releaseStick);
for(const key of ['gas','brake','boost']){const b=$(`touch-${key}`);b.addEventListener('pointerdown',e=>{e.preventDefault();controlPointers.set(e.pointerId,key);touch[key]=true;b.setPointerCapture(e.pointerId);b.style.filter='brightness(1.35)';engine.unlock();});const release=e=>{if(controlPointers.get(e.pointerId)===key){controlPointers.delete(e.pointerId);touch[key]=[...controlPointers.values()].includes(key);b.style.filter='';}};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);b.addEventListener('contextmenu',e=>e.preventDefault());}
window.addEventListener('contextmenu',e=>{if(mode!=='garage')e.preventDefault();});
function prepareMinimap(){minimapPoints=Array.from({length:200},(_,i)=>data.sample(i/200).p);const xs=minimapPoints.map(p=>p.x),zs=minimapPoints.map(p=>p.z);mapBounds={minX:Math.min(...xs),maxX:Math.max(...xs),minZ:Math.min(...zs),maxZ:Math.max(...zs)};}
function drawMinimap(){const ctx=mapCtx,w=220,h=170,b=mapBounds,scale=Math.min((w-30)/(b.maxX-b.minX),(h-30)/(b.maxZ-b.minZ));const project=p=>({x:w/2+(p.x-(b.minX+b.maxX)/2)*scale,y:h/2+(p.z-(b.minZ+b.maxZ)/2)*scale});ctx.clearRect(0,0,w,h);ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();minimapPoints.forEach((p,i)=>{const q=project(p);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y);});ctx.closePath();ctx.strokeStyle='#122b4480';ctx.lineWidth=9;ctx.stroke();ctx.strokeStyle='#ffffff99';ctx.lineWidth=3;ctx.stroke();for(const r of [...race.bots,race.player]){const p=project(data.sample(r.progress/data.length).p);ctx.beginPath();ctx.arc(p.x,p.y,r===race.player?5:3,0,Math.PI*2);ctx.fillStyle=r===race.player?'#ff7855':'#fff8';ctx.fill();if(r===race.player){ctx.strokeStyle='white';ctx.lineWidth=1.5;ctx.stroke();}}}
function updateRacerModels(dt){
  const p=race.player;updateBikePose(playerBike,data,p.progress,p.offset,p.steer,p.speed,dt,{wheelie:p.wheelie,stoppie:p.stoppie,dirty:p.helmetDirty,lean:p.rescue?0:null});
  playerBike.userData.shadow.visible=!p.rescue;
  if(p.rescue){const pose=p.rescue.pose;playerBike.position.y+=pose.height;playerBike.rotation.z=pose.roll;world.parrot.visible=pose.bird;if(pose.bird){world.parrot.position.copy(playerBike.position);world.parrot.position.y+=3.5;world.parrot.rotation.y=playerBike.rotation.y+Math.PI;world.parrot.userData.cords.visible=pose.carrying;if(!pose.carrying&&p.rescue.elapsed<1.05){const approach=clamp((1.05-p.rescue.elapsed)/.4,0,1);world.parrot.position.addScaledVector(data.sample(p.progress/data.length).side,approach*12);world.parrot.position.y+=approach*4;}}}
  else if(birdFarewell>0){birdFarewell=Math.max(0,birdFarewell-dt);world.parrot.visible=birdFarewell>0;world.parrot.userData.cords.visible=false;world.parrot.position.y+=dt*5;world.parrot.position.addScaledVector(data.sample(p.progress/data.length).side,dt*6);if(!birdFarewell)$('parrot-caption').classList.add('hidden');}else world.parrot.visible=false;
  if(world.parrot.visible)animateParrot(world.parrot,viewTime);
  for(let i=0;i<race.bots.length;i++){const b=race.bots[i],curve=data.curvature(b.progress/data.length);updateBikePose(botBikes[i],data,b.progress,b.offset,0,b.speed,dt,{lean:clamp(-curve*b.speed*b.speed*.065,-.77,.77),wheelie:data.pads.some(t=>Math.abs(wrap(b.progress/data.length,1)-t)<.012)?.7:0});}
}
const lookTarget=new THREE.Vector3(),wantedCamera=new THREE.Vector3();
function updateCamera(dt,snap=false){const p=race.player,{p:pos,tangent,side}=data.sample(p.progress/data.length);const distance=8.1+(p.boostActive?1.6:0);wantedCamera.copy(playerBike.position).addScaledVector(tangent,-distance);wantedCamera.y+=3.7;const look=playerBike.position.clone().addScaledVector(tangent,8);look.y+=1.1;
  if(p.rescue){wantedCamera.copy(pos).addScaledVector(tangent,-12).addScaledVector(side,p.offset*.45);wantedCamera.y+=7;look.copy(playerBike.position);look.y+=2.4;}
  if(snap){camera.position.copy(wantedCamera);lookTarget.copy(look);}else{camera.position.lerp(wantedCamera,1-Math.exp(-dt*(p.rescue?3:7)));lookTarget.lerp(look,1-Math.exp(-dt*6));}camera.lookAt(lookTarget);camera.fov=THREE.MathUtils.damp(camera.fov,p.rescue?64:p.boostActive?58:49,4,dt);camera.updateProjectionMatrix();}
function updateHud(){const p=race.player;$('speed').textContent=String(Math.round(p.speed*3.6));$('speed-fill').style.width=`${p.speed/race.boostSpeed*100}%`;$('boost-fill').style.width=`${p.boost*100}%`;$('boost-fill').style.background=p.boostActive?'#fff0bc':'#ffd477';$('position').innerHTML=`${race.position}<span>/6</span>`;$('race-time').textContent=formatTime(race.time);$('hud-lap').textContent=`RUNDE ${p.lap} / ${TOTAL_LAPS}`;const stunt=!p.rescue&&(p.stoppie>.2?'STOPPIE!':p.wheelie>.3?'WHEELIE!':'');$('stunt-label').textContent=stunt||'';$('stunt-label').classList.toggle('active',!!stunt);drawMinimap();}
function parrotSquawk(){if(!sound)return;engine.unlock();if(audio){const o=audio.ctx.createOscillator(),g=audio.ctx.createGain();o.type='sawtooth';o.frequency.setValueAtTime(930,audio.ctx.currentTime);o.frequency.exponentialRampToValueAtTime(260,audio.ctx.currentTime+.18);g.gain.setValueAtTime(.16,audio.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.ctx.currentTime+.2);o.connect(g);g.connect(audio.master);o.start();o.stop(audio.ctx.currentTime+.21);}if('speechSynthesis' in window){window.speechSynthesis.cancel();const line=new SpeechSynthesisUtterance('Haha, du Lappen!');line.lang='de-DE';line.pitch=1.75;line.rate=1.12;line.volume=.9;const voice=window.speechSynthesis.getVoices().find(v=>v.lang.startsWith('de')&&v.localService);if(voice)line.voice=voice;window.speechSynthesis.speak(line);}}
function finishRace(){if(finishShown)return;finishShown=true;mode='finished';clearInput();$('countdown').textContent='';const p=race.player,place=race.position;const previous=storage.get(recordKey(selectedTrack,selectedConfig));const record=!previous||p.finishTime<previous;if(record)storage.set(recordKey(selectedTrack,selectedConfig),p.finishTime);$('finish-place').innerHTML=`${place}<span>. PLATZ</span>`;$('finish-title').textContent=place===1?'Die Strecke gehört dir.':place<=3?'Ein Ride fürs Podium.':'Das nächste Rennen gehört dir.';$('finish-time').textContent=formatTime(p.finishTime);$('finish-lap').textContent=formatTime(Math.min(...p.laps));$('record-note').textContent=record?'✦ NEUE PERSÖNLICHE BESTZEIT':`Persönliche Bestzeit: ${formatTime(previous)}`;const board=$('leaderboard');board.replaceChildren();race.standings.forEach((r,i)=>{const row=document.createElement('div');if(r===p)row.className='player-row';const rank=document.createElement('span');rank.textContent=String(i+1).padStart(2,'0');const name=document.createElement('span');name.textContent=r.name;const time=document.createElement('span');time.textContent=r.finished?formatTime(r.finishTime):'noch auf der Strecke';row.append(rank,name,time);board.append(row);});$('results-overlay').classList.remove('hidden');$('again-button').focus({preventScroll:true});engine.beep(880,.4);}
function updateRace(dt){
  if(mode==='countdown'){
    countdown-=dt;const count=Math.ceil(countdown-.5);if(count!==lastCount){lastCount=count;$('countdown').textContent=count>0?String(count):'LOS!';$('countdown').classList.remove('pop');void $('countdown').offsetWidth;$('countdown').classList.add('pop');engine.beep(count>0?480:960,count>0?.1:.3);}if(countdown<=0){mode='race';elapsed=0;showMessage('DEIN RENNEN. DEIN STYLE.',2);}return;
  }
  if(mode!=='race')return;
  elapsed+=dt;if(elapsed>.8)$('countdown').textContent='';
  accumulator+=dt;while(accumulator>=1/100){race.update(1/100,input());for(const event of race.events){if(event.type==='pad'){showMessage('⚡ BOOST-FELD',1);engine.beep(1050,.13);}if(event.type==='lap')showMessage(race.player.lap===3?'LETZTE RUNDE!':'RUNDE 2 — WEITER SO!',2);if(event.type==='collision')showMessage('KONTAKT! BLEIB DRAN.',1);if(event.type==='fall'){showMessage('ABFLUG! PAPAGEIEN-SERVICE IST UNTERWEGS.',1.2);}if(event.type==='parrot'){$('parrot-caption').classList.remove('hidden');parrotSquawk();}if(event.type==='splat'){showMessage('HELM-TREFFER!',1);}if(event.type==='rescued'){birdFarewell=1.2;showMessage('WIEDER AUF DER STRECKE!',1.5);}if(event.type==='edge')showMessage('KURZ BREMSEN, SAUBER EINLENKEN',1.8);if(event.type==='finish')finishRace();}accumulator-=1/100;if(mode==='finished')break;}
}
function showroomCamera(){const portrait=innerWidth<700&&innerHeight>innerWidth;const compact=innerHeight<600&&innerWidth>innerHeight;
  // The camera framing leaves the left side to the headline and the bottom to setup.
  camera.fov=portrait?43:compact?43:40;camera.aspect=innerWidth/innerHeight;
  showroom.bike.rotation.y=garageRotation-.15;
  if(portrait){camera.position.set(9.5,4.6,11.3);camera.lookAt(0,1.4,0);camera.setViewOffset(innerWidth,innerHeight,0,-innerHeight*.025,innerWidth,innerHeight);}
  else{camera.clearViewOffset();const zoom=selectedConfig.passenger?1.13:1;camera.position.set(6.3*zoom,3.2*zoom,7.8*zoom);camera.lookAt(-2.3,selectedConfig.passenger?.15:-.1,0);camera.setViewOffset(innerWidth,innerHeight,0,innerHeight*(compact?.075:.115),innerWidth,innerHeight);}
  camera.updateProjectionMatrix();
}
function resize(){renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));camera.aspect=innerWidth/innerHeight;camera.clearViewOffset();camera.updateProjectionMatrix();if(mode!=='garage'){if(matchMedia('(pointer:coarse)').matches&&innerHeight>innerWidth)pauseRace();if(playerBike)updateCamera(1,true);}}
window.addEventListener('resize',resize);
let previousFrame=performance.now(),hudClock=0;function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-previousFrame)/1000,.25);previousFrame=now;viewTime+=dt;
  if(mode==='garage')showroomCamera();else{camera.clearViewOffset();updateRace(dt);if(mode!=='paused'){updateRacerModels(dt);updateCamera(dt);if(world)world.pads.forEach((p,i)=>p.children[0].material.emissiveIntensity=.3+Math.sin(viewTime*5+i)*.15);}hudClock+=dt;if(hudClock>.065){updateHud();hudClock=0;}}
  if(messageTimer>0){messageTimer-=dt;if(messageTimer<=0)$('race-message').classList.remove('visible');}engine.update();renderer.render(activeScene,camera);
}
showroomCamera();renderer.render(activeScene,camera);$('loading').style.opacity=0;setTimeout(()=>$('loading').classList.add('hidden'),450);requestAnimationFrame(frame);
